package com.zafiro.wxentry.kernel;
import java.util.*;
public final class SnsLocalProjectionTest {
 static int checks;static void ok(boolean value){checks++;if(!value)throw new AssertionError("projection "+checks);}
 public static void main(String[] args){String owner="wxid_owner",a=owner+"~1",b=owner+"~2",other="wxid_other~3";
  SnsLocalData.Person p=new SnsLocalData.Person("wxid_friend","好友");SnsLocalData.Comment c=new SnsLocalData.Comment("local_11111111111111111111111111111111",p,"评论");
  SnsLocalData data=SnsLocalData.empty().enabled(SnsLocalData.Feature.LIKES,true).enabled(SnsLocalData.Feature.COMMENTS,true).likes(a,Arrays.asList(p),1).addComments(a,Arrays.asList(c),1).likes(b,Arrays.asList(p),2).likes(other,Arrays.asList(p),3);
  ok(SnsLocalProjection.extraLikes(data,data.posts.get(a),Collections.<String>emptySet())==1);ok(SnsLocalProjection.extraLikes(data,data.posts.get(a),Collections.singleton(p.id))==0);ok(SnsLocalProjection.extraLikes(data.enabled(SnsLocalData.Feature.LIKES,false),data.posts.get(a),Collections.<String>emptySet())==0);ok(SnsLocalProjection.extraLikes(data,null,Collections.<String>emptySet())==0);
  Set<String> available=new HashSet<String>(Arrays.asList(a,b,other));SnsLocalProjection.Page page=SnsLocalProjection.messages(owner,data,available,100);ok(page.total==3&&page.entries.size()==3);ok(page.entries.get(0).key.equals(b));ok(page.entries.get(1).comment==c||page.entries.get(2).comment==c);ok(!page.entries.get(1).id.equals(page.entries.get(2).id));
  page=SnsLocalProjection.messages(owner,data,available,1);ok(page.total==3&&page.entries.size()==1);ok(SnsLocalProjection.messages(owner,data,Collections.singleton(a),100).total==2);ok(SnsLocalProjection.messages("wxid_stranger",data,available,100).total==0);ok(SnsLocalProjection.messages(null,data,available,100).total==0);
  ok(SnsLocalProjection.messages(owner,data.enabled(SnsLocalData.Feature.LIKES,false),available,100).total==1);ok(SnsLocalProjection.messages(owner,data.enabled(SnsLocalData.Feature.COMMENTS,false),available,100).total==2);ok(SnsLocalProjection.messages(owner,data.clear(a),available,100).total==1);ok(SnsLocalProjection.messages(owner,data.clear(),available,100).total==0);ok(SnsLocalProjection.messages(owner,data,available,0).total==0);
  Map<String,Long> times=new HashMap<String,Long>();times.put(a+"/"+c.localId,100L);page=SnsLocalProjection.messages(owner,data,available,1,times);ok(page.entries.get(0).comment==c&&page.entries.get(0).time==100L);
  List<SnsLocalProjection.Entry> local=SnsLocalProjection.messages(owner,data,available,100,times).entries;int[] merged=SnsLocalProjection.merge(new long[]{200,50,0},local,false);List<Integer> natives=new ArrayList<Integer>();List<Integer> locals=new ArrayList<Integer>();long last=Long.MAX_VALUE;for(int ref:merged){long time=ref>=0?new long[]{200,50,0}[ref]:local.get(-1-ref).time;ok(time<=last);last=time;if(ref>=0)natives.add(ref);else locals.add(-1-ref);}ok(natives.equals(Arrays.asList(0,1,2)));ok(locals.equals(Arrays.asList(0,1,2)));ok(SnsLocalProjection.merge(new long[0],local,true).length==local.size()+1);ok(SnsLocalProjection.merge(new long[]{2,1},Collections.<SnsLocalProjection.Entry>emptyList(),false).length==2);
  for(int before:new int[]{0,1,100})for(int nativeCount:new int[]{0,1,50})for(int after:new int[]{0,1,100}){SnsLocalProjection.Layout layout=new SnsLocalProjection.Layout(before,nativeCount,after);ok(layout.count()==before+nativeCount+after);for(int n=0;n<nativeCount;n++)ok(layout.nativePosition(before+n)==n);ok(layout.delegatedPosition(layout.count())==nativeCount);ok(layout.delegatedPosition(layout.count()+1)==nativeCount+1);if(before>0)ok(layout.delegatedPosition(0)==-1);if(after>0)ok(layout.delegatedPosition(layout.count()-1)==-1);}
  ok(SnsLocalProjection.own(owner,a));ok(!SnsLocalProjection.own("wxid_ow",a));ok(!SnsLocalProjection.own(owner,owner+"~0"));
  System.out.println("PASS "+checks+" local Moments cross-surface projection, account boundaries, paging, independent switches and native position preservation checks");
 }
}
